import{_ as e,c as i,o as t,a3 as r}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/introduction.md","filePath":"zh-CN/guide/introduction.md","lastUpdated":1786595765000}'),l={name:"zh-CN/guide/introduction.md"};function o(n,a,s,h,d,c){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><h2 id="关于-clipboardxai" tabindex="-1">关于 ClipboardxAI <a class="header-anchor" href="#关于-clipboardxai" aria-label="Permalink to &quot;关于 ClipboardxAI&quot;">​</a></h2><p><strong>ClipboardxAI</strong> 是一款面向 macOS 的智能剪贴板管理器。每当你复制文本、代码或链接时，它都会保存到菜单栏中一处可搜索的历史记录里。只需点击一下——或者完全自动地——你就能对该剪贴内容执行一项操作：总结、翻译、整理，或交给云端 AI 模型处理。</p><p>它围绕两类工具构建：</p><ul><li><strong>内置本地工具</strong>：完全在你的 Mac 上运行，无需联网。</li><li><strong>AI 操作</strong>：调用你自行配置的云端模型（使用你自己的 API key，保存在系统 Keychain 中）。</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="📋-剪贴板历史" tabindex="-1">📋 剪贴板历史 <a class="header-anchor" href="#📋-剪贴板历史" aria-label="Permalink to &quot;📋 剪贴板历史&quot;">​</a></h3><p>你复制的一切都会被自动捕获，并保存在可搜索的历史记录中。从菜单栏随时回到任意一条历史剪贴内容——再也不用担心片段丢失。</p><h3 id="⚡-智能建议" tabindex="-1">⚡ 智能建议 <a class="header-anchor" href="#⚡-智能建议" aria-label="Permalink to &quot;⚡ 智能建议&quot;">​</a></h3><p>ClipboardxAI 会根据当前剪贴内容，推荐最相关的操作。你可以接受建议，也可以浏览完整的工具列表。</p><h3 id="🛠️-内置本地工具" tabindex="-1">🛠️ 内置本地工具 <a class="header-anchor" href="#🛠️-内置本地工具" aria-label="Permalink to &quot;🛠️ 内置本地工具&quot;">​</a></h3><p>离线、私密、即时：</p><ul><li><strong>提取链接（Extract Links）</strong>——从一段文本中抽出所有 URL。</li><li><strong>字数统计（Count Stats）</strong>——统计单词、字符、行数和句子数。</li><li><strong>压缩空行（Collapse Blank Lines）</strong>——一步整理粘贴的文本。</li></ul><p>未来还会持续增加更多本地工具——它们永远不会离开你的设备。</p><h3 id="✨-ai-操作" tabindex="-1">✨ AI 操作 <a class="header-anchor" href="#✨-ai-操作" aria-label="Permalink to &quot;✨ AI 操作&quot;">​</a></h3><p>将当前剪贴内容发送到云端模型，以：</p><ul><li>**总结（Summarize）**长文章与长篇讨论。</li><li>**翻译（Translate）**不同语言之间的内容。</li><li>**改写 / 润色（Rewrite / polish）**语气与表达。</li><li>运行 <strong>Marketplace</strong> 中的任意操作。</li></ul><h3 id="🛒-操作市场-action-marketplace" tabindex="-1">🛒 操作市场（Action Marketplace） <a class="header-anchor" href="#🛒-操作市场-action-marketplace" aria-label="Permalink to &quot;🛒 操作市场（Action Marketplace）&quot;">​</a></h3><p>浏览社区创建的 AI 操作，并通过深链接（<code>clipboardxai://install?action=&lt;id&gt;</code>）一键安装。分类包括：写作、开发、效率、翻译、社交与分析。</p><h3 id="🔒-以隐私为本" tabindex="-1">🔒 以隐私为本 <a class="header-anchor" href="#🔒-以隐私为本" aria-label="Permalink to &quot;🔒 以隐私为本&quot;">​</a></h3><p>你的剪贴板历史始终留在你的设备上。云端 AI 是<strong>可选开启</strong>的：开启后，内容只会发送到你<em>自己</em>选择的提供商，使用的是保存在你 Keychain 中的 API key。我们从不接收或存储你的剪贴内容，也没有任何分析或遥测。</p><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><ul><li><strong>操作系统</strong>：macOS 14 Sonoma 或更高版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）或 Intel（64 位）</li><li><strong>内存</strong>：最低 4 GB，推荐 8 GB</li><li><strong>存储空间</strong>：安装约需 50 MB</li><li><strong>云端 AI 所需</strong>：来自受支持提供商（DeepSeek、MiniMax、Zhipu GLM、Kimi、Mistral、Ollama、OpenAI、Anthropic 或 Gemini）的 API key</li></ul><h2 id="支持的语言" tabindex="-1">支持的语言 <a class="header-anchor" href="#支持的语言" aria-label="Permalink to &quot;支持的语言&quot;">​</a></h2><p>本应用与本站支持 7 种语言：English、简体中文、繁體中文、日本語、德语、西班牙语、法语。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>如果你是 ClipboardxAI 的新用户，请先阅读<a href="/zh-CN/guide/installation.html">安装指南</a>在 Mac 上运行本应用，再阅读<a href="/zh-CN/guide/usage.html">使用说明</a>了解操作的使用方式。</p>',27)])])}const g=e(l,[["render",o]]);export{u as __pageData,g as default};
